={{
    (function pick() {
      const ordem = ['Call Kadu - Principal', 'caduPreAvaliacao', 'caduPreSimulacao', 'Gabi_Instagram'];
      for (const name of ordem) {
        try {
          const n = $(name);
          if (n.all().length > 0 && Object.keys(n.item?.json ?? {}).length > 0) {
            return n.item.json.output ?? {};
          }
        } catch (e) { /* nó não executou ou não existe — ignora e segue */ }
      }
      return {};
    })()
  }}
